 ("FAWOS","Fachstelle für Wohnungssicherung der Volkshilfe Wien.",[("msp",28),("msp",30)]),
 ("KSOW / bzWO","Service-Center des FSW für die Förderung von WWH-Leistungen.",[("msk",90),("msp",45)]),
 ("SOWO","Soziales Wohnungsmanagement: erschließt und verwaltet leistbaren Wohnraum.",[("msk",99)]),
 ("mobeWO","Mobil betreutes Wohnen.",[("msk",98)]),
 ("IBV","Informationsbevollmächtigte Person beim Betreuten Konto.",[("msk",125)]),
 ("Exekutionstitel","Rechtskräftige Grundlage für die zwangsweise Hereinbringung.",[("msp",62)]),
 ("Drittschuldner","Arbeitgeber oder auszahlende Stelle bei der Gehaltsexekution.",[("msp",63),("msp",64)]),
 ("Fiktive Anrechnung","Einkommen zählt, obwohl es nicht ausbezahlt wird.",[("msk",46)]),
 ("Anspannungsgrundsatz","Unterhalt nach dem, was man verdienen könnte.",[("msk",107)]),
 ("Kostenersatz","Ersatz der WMS der letzten drei Jahre, wenn Vermögen nicht aus eigener Arbeit dazukommt.",[("msk",51)]),
 ("Mutterschutz","Beschäftigungsverbot ab der 8. Woche vor der Geburt, in dieser Zeit gibt es Wochengeld.",[("msk",15)]),
 ("Karenz","Arbeitsrechtliche Freistellung nach der Geburt, nicht dasselbe wie Kinderbetreuungsgeld.",[("msk",17)]),
 ("Partnerschaftsbonus","Einmalige Zahlung, wenn beide Eltern das KBG etwa gleich lang beziehen.",[("msk",16)]),
 ("Arbeitnehmer*innenveranlagung","Steuerausgleich beim Finanzamt, bis 5 Jahre rückwirkend; holt Familienbonus und Absetzbeträge.",[("msk",20)]),
